package main
import("encoding/json";"flag";"fmt";"os";"github.com/Jamf-Concepts/jamf-cli/internal/profileconvert")
type response struct{Success bool `json:"success"`;DisplayName string `json:"displayName,omitempty"`;Components []profileconvert.DDMComponent `json:"components,omitempty"`;Warnings []string `json:"warnings,omitempty"`;Conversions []string `json:"conversions,omitempty"`;Error string `json:"error,omitempty"`}
func main(){input:=flag.String("input","","mobileconfig input");flag.Parse();if *input==""{emit(response{Error:"--input is required"},2)};data,err:=os.ReadFile(*input);if err!=nil{emit(response{Error:err.Error()},1)};result,err:=profileconvert.ConvertToDDMComponents(data,true,nil);if err!=nil{emit(response{Error:err.Error()},1)};components:=append([]profileconvert.DDMComponent{},result.NativeComponents...);if result.ProfileConfig!=nil{components=append(components,profileconvert.DDMComponent{Identifier:"com.jamf.ddm-configuration-profile",Configuration:result.ProfileConfig})};if len(components)==0{emit(response{Error:"no components produced"},1)};emit(response{Success:true,DisplayName:result.DisplayName,Components:components,Warnings:result.Warnings,Conversions:result.Conversions},0)}
func emit(v response,code int){if err:=json.NewEncoder(os.Stdout).Encode(v);err!=nil{fmt.Fprintln(os.Stderr,err);os.Exit(1)};os.Exit(code)}
